public class Main { public static void main(String[] args) {var s=new java.util.Scanner(System.in); int[][] a={{-3,0,3},{2,-1,0},{1,3,-2}};if(s.hasNextInt())for(int r=0;r<3;r++)for(int c=0;c<3;c++)a[r][c]=s.nextInt();double[][] b=new double[3][3];for(int r=0;r<3;r++){double mean=(a[r][0]+a[r][1]+a[r][2])/3d;for(int c=0;c<3;c++)b[r][c]=a[r][c]-mean;}for(double[] row:b){for(double v:row)System.out.printf(java.util.Locale.ROOT,"%.12e ",v);System.out.print("\r\n");}} }
